update_rule.pseudocode:
if t == 0:
  set random seed
  if network_type == 'small_world':
    G = watts_strogatz_graph(N=population_size, k=avg_degree, p=rewiring_prob)
  else if network_type == 'erdos_renyi': G = erdos_renyi_graph(...)
  else: G = build_custom_network()
  for each person i:
    Person[i].network_neighbors = neighbors(G, i)
  output network.graph = G

if t == 0:
  sample household sizes from household_size_distribution to sum to N
  assign persons to households sequentially
  for each household h:
    draw income from lognormal matching income_mean, income_std
    set household_norms = initial_mask_adoption_rate + noise
    set location = random region index
  for each person i:
    set household_id accordingly

if day == 0:
  cf_prev = observable.adoption_rate_daily
if day < mandate_start_day:
  cf_prev = counterfactual_smoothing_alpha * observable.adoption_rate_daily + (1 - counterfactual_smoothing_alpha) * cf_prev
  observable.adoption_rate_daily_counterfactual = cf_prev
else:
  observable.adoption_rate_daily_counterfactual = cf_prev = counterfactual_smoothing_alpha * cf_prev + (1 - counterfactual_smoothing_alpha) * cf_prev  # carry forward smoothing
